// What caused a status transition. An enum because the cycle-time metrics filter on
// it -- "time from AUTHORIZE to ASSIGN" is a question asked of this field, and
// asking it of free text means every caller agreeing on spelling forever.
type AgentStatusTrigger string

const (
	AgentStatusTriggerRegister      AgentStatusTrigger = "REGISTER"
	AgentStatusTriggerAuthorize     AgentStatusTrigger = "AUTHORIZE"
	AgentStatusTriggerAssign        AgentStatusTrigger = "ASSIGN"
	AgentStatusTriggerSignoff       AgentStatusTrigger = "SIGNOFF"
	AgentStatusTriggerReturn        AgentStatusTrigger = "RETURN"
	AgentStatusTriggerComplete      AgentStatusTrigger = "COMPLETE"
	AgentStatusTriggerCancel        AgentStatusTrigger = "CANCEL"
	AgentStatusTriggerSplit         AgentStatusTrigger = "SPLIT"
	AgentStatusTriggerHold          AgentStatusTrigger = "HOLD"
	AgentStatusTriggerLiftHold      AgentStatusTrigger = "LIFT_HOLD"
	AgentStatusTriggerHumanGate     AgentStatusTrigger = "HUMAN_GATE"
	AgentStatusTriggerHumanAccept   AgentStatusTrigger = "HUMAN_ACCEPT"
	AgentStatusTriggerHumanReject   AgentStatusTrigger = "HUMAN_REJECT"
	AgentStatusTriggerHumanSignoff  AgentStatusTrigger = "HUMAN_SIGNOFF"
	AgentStatusTriggerSessionClosed AgentStatusTrigger = "SESSION_CLOSED"
	// A person unassigned the task, back to the queue, with a reason (task RD3-4).
	AgentStatusTriggerUnassign AgentStatusTrigger = "UNASSIGN"
	// The board completed a task whose loop ran out -- a cycle cap, a no-progress stop or a budget --
	// with items left open below what the board requires resolved. Distinct from COMPLETE: the work
	// finished in one case and the loop stopped in the other.
	AgentStatusTriggerPolicyComplete AgentStatusTrigger = "POLICY_COMPLETE"
	// A completed task sent back to a role, with a reason. A decision, not a loop.
	AgentStatusTriggerReopen AgentStatusTrigger = "REOPEN"
	// The work passed and a linked PR is not merged yet: into DELIVERING.
	AgentStatusTriggerDeliverWait AgentStatusTrigger = "DELIVER_WAIT"
	// Every linked PR merged: DELIVERING to COMPLETED.
	AgentStatusTriggerDelivered AgentStatusTrigger = "DELIVERED"
	// A linked PR closed without merging: to the coordinator.
	AgentStatusTriggerPrClosed AgentStatusTrigger = "PR_CLOSED"
	// A delivery unit was declared abandoned: to the coordinator (task 18c5c293).
	AgentStatusTriggerDeliveryAbandoned AgentStatusTrigger = "DELIVERY_ABANDONED"
)

var AllAgentStatusTrigger = []AgentStatusTrigger{
	AgentStatusTriggerRegister,
	AgentStatusTriggerAuthorize,
	AgentStatusTriggerAssign,
	AgentStatusTriggerSignoff,
	AgentStatusTriggerReturn,
	AgentStatusTriggerComplete,
	AgentStatusTriggerCancel,
	AgentStatusTriggerSplit,
	AgentStatusTriggerHold,
	AgentStatusTriggerLiftHold,
	AgentStatusTriggerHumanGate,
	AgentStatusTriggerHumanAccept,
	AgentStatusTriggerHumanReject,
	AgentStatusTriggerHumanSignoff,
	AgentStatusTriggerSessionClosed,
	AgentStatusTriggerUnassign,
	AgentStatusTriggerPolicyComplete,
	AgentStatusTriggerReopen,
	AgentStatusTriggerDeliverWait,
	AgentStatusTriggerDelivered,
	AgentStatusTriggerPrClosed,
	AgentStatusTriggerDeliveryAbandoned,
}

