// Well-known specification documents. When an identifier's idType is SPECIFICATION its idValue is
// one of these values -- the design-stage counterpart of TEA's compliance-document-type, so a
// document set is discoverable by identifier rather than by naming convention.
type SpecificationType string

const (
	SpecificationTypeConops           SpecificationType = "CONOPS"
	SpecificationTypeUseCases         SpecificationType = "USE_CASES"
	SpecificationTypeRequirements     SpecificationType = "REQUIREMENTS"
	SpecificationTypeFunctions        SpecificationType = "FUNCTIONS"
	SpecificationTypeProductBreakdown SpecificationType = "PRODUCT_BREAKDOWN"
	SpecificationTypeInterfaces       SpecificationType = "INTERFACES"
	SpecificationTypeDataModel        SpecificationType = "DATA_MODEL"
	SpecificationTypeArchitecture     SpecificationType = "ARCHITECTURE"
	SpecificationTypeDetailedDesign   SpecificationType = "DETAILED_DESIGN"
	SpecificationTypeUxConcept        SpecificationType = "UX_CONCEPT"
	SpecificationTypeTestPlan         SpecificationType = "TEST_PLAN"
	SpecificationTypeGlossary         SpecificationType = "GLOSSARY"
	SpecificationTypeDecisionRecord   SpecificationType = "DECISION_RECORD"
	// One review round of one task. Task-scoped: one component per board target holds every task's rounds.
	SpecificationTypeBoardReviewItems SpecificationType = "BOARD_REVIEW_ITEMS"
	// One test run of one task. Task-scoped, like BOARD_REVIEW_ITEMS.
	SpecificationTypeBoardTestReport SpecificationType = "BOARD_TEST_REPORT"
	// What one hop could not proceed without knowing. Task-scoped, like BOARD_REVIEW_ITEMS, and
	// usually published with no file at all -- the items are the document.
	SpecificationTypeBoardQuestions SpecificationType = "BOARD_QUESTIONS"
	// What the element checks found on one document of one task (gaps §2.A). Task-scoped and always
	// index-only: the board cuts it, no agent publishes it, and it has no path.
	SpecificationTypeBoardElementCheckReport SpecificationType = "BOARD_ELEMENT_CHECK_REPORT"
	// What one investigation found (task RD4-12): the deliverable of an INVESTIGATION task, which comes back
	// pinned on the task that commissioned it. Task-scoped prose whose elements are references only.
	SpecificationTypeBoardInvestigationReport SpecificationType = "BOARD_INVESTIGATION_REPORT"
)

var AllSpecificationType = []SpecificationType{
	SpecificationTypeConops,
	SpecificationTypeUseCases,
	SpecificationTypeRequirements,
	SpecificationTypeFunctions,
	SpecificationTypeProductBreakdown,
	SpecificationTypeInterfaces,
	SpecificationTypeDataModel,
	SpecificationTypeArchitecture,
	SpecificationTypeDetailedDesign,
	SpecificationTypeUxConcept,
	SpecificationTypeTestPlan,
	SpecificationTypeGlossary,
	SpecificationTypeDecisionRecord,
	SpecificationTypeBoardReviewItems,
	SpecificationTypeBoardTestReport,
	SpecificationTypeBoardQuestions,
	SpecificationTypeBoardElementCheckReport,
	SpecificationTypeBoardInvestigationReport,
}

